// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { UndirectedGraph } from "graphology";
import louvain from "graphology-communities-louvain";
import { estimatedNodeLabelWidth, ellipsizeNodeLabel } from "../../../main/frontend/graph-explorer/graph-geometry.ts";
import { releaseGraphLayoutWorker, startGraphLayout, warmGraphLayoutWorker } from "../../../main/frontend/graph-explorer/graph-layout-client.ts";
import { layoutCommunities, layoutTopology } from "../../../main/frontend/graph-explorer/graph-layout-topology.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";
import { BoundedCache, utf8Length } from "../../../main/frontend/graph-explorer/request-batching.ts";
import { compactTerm, predicateLabel } from "../../../main/frontend/graph-explorer/graph-terms.ts";
import { isSafeSparqlIri, isSparqlTerm, sparqlNodeId } from "../../../main/frontend/graph-explorer/rdf-terms.ts";
import { representativeResults } from "./fixtures/representative-graph.mjs";

/**
 * The large-graph speed-ups replace straightforward code with faster code that must compute exactly the same thing.
 * Each test keeps the straightforward version as the reference and compares the two on ordinary and awkward inputs.
 */
const SAMPLES = [
  "", " ", "a", "Plain label", "iiiiii", "WWWWMM@@", "Label 12 — with dash", "ilI1'.,:;|!", "mwMW@%&", "AZaz09",
  "Ærøskøbing", "雪-🦊", "😀😀", "é", "\ud800", "x\udc00y", "\t\n", "a".repeat(300), "Résumé of 2026 (draft)",
];

// The width estimate as it was: a regex per character.
function referenceLabelWidth(label) {
  return [...label].reduce((width, character) => {
    if (character === " ") return width + 3.8;
    if (/[ilI1'.,:;|!]/.test(character)) return width + 3.7;
    if (/[mwMW@%&]/.test(character)) return width + 9.7;
    if (/[A-Z0-9]/.test(character)) return width + 7.4;
    return width + 6.5;
  }, 0);
}

test("label widths are bit-for-bit the regex estimate they replace", () => {
  const every = Array.from({ length: 128 }, (_, code) => String.fromCharCode(code)).join("");
  for (const label of [...SAMPLES, every, [...every].reverse().join("")]) {
    assert.equal(Object.is(estimatedNodeLabelWidth(label), referenceLabelWidth(label)), true, JSON.stringify(label));
  }
  for (const label of SAMPLES) {
    for (const max of [0, 10, 40, 120]) {
      const shown = ellipsizeNodeLabel(label, max);
      assert.ok(shown === label || shown.endsWith("…"), JSON.stringify([label, max]));
    }
  }
});

test("UTF-8 lengths match TextEncoder, including lone surrogates", () => {
  const encoder = new TextEncoder();
  for (const text of [...SAMPLES, JSON.stringify(SAMPLES), "\ud83d", "\ud83d😀", "\udfff\ud800"]) {
    assert.equal(utf8Length(text), encoder.encode(text).byteLength, JSON.stringify(text));
  }
});

test("the label cache accounts the same bytes, given the value's JSON or not", () => {
  const encoder = new TextEncoder();
  const value = { candidates: [{ value: "雪-🦊 label", language: "nb", property: "urn:p" }], checked: true };
  const expected = (key) => encoder.encode(JSON.stringify([key, value])).byteLength;
  const plain = new BoundedCache(10, 1_000_000);
  const given = new BoundedCache(10, 1_000_000);
  for (const key of ["urn:a", "ns\nurn:é", "\ud800key"]) {
    plain.set(key, value, 1000);
    given.set(key, value, 1000, JSON.stringify(value));
  }
  const total = ["urn:a", "ns\nurn:é", "\ud800key"].reduce((sum, key) => sum + expected(key), 0);
  assert.equal(plain.bytes, total);
  assert.equal(given.bytes, total);

  const bounded = new BoundedCache(10, expected("urn:a") + expected("urn:b"));
  for (const key of ["urn:a", "urn:b", "urn:c"]) bounded.set(key, value, 1000, JSON.stringify(value));
  assert.deepEqual(bounded.snapshot().map(([key]) => key), ["urn:b", "urn:c"], "the byte bound evicts the oldest");
});

// The topology as it was: graphology's own duplicate check and generated edge keys.
function referenceTopology(graph) {
  const topology = new UndirectedGraph();
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  graph.nodes.forEach((_, i) => topology.addNode(String(i)));
  graph.edges.forEach((edge) => {
    const a = index.get(edge.source), b = index.get(edge.target);
    if (a !== undefined && b !== undefined && a !== b && !topology.hasEdge(a, b)) topology.addEdge(a, b);
  });
  return topology;
}

const shape = (topology) => ({
  nodes: topology.nodes(),
  edges: topology.mapEdges((_key, _attributes, source, target) => [source, target]),
});

test("the layout topology keeps the nodes, the pairs and their order, and so the communities", () => {
  const node = (id) => ({ id, label: id, kind: "iri" });
  const edge = (source, target) => ({ id: `${source}-${target}`, source, target, predicate: "urn:p", label: "p" });
  const small = {
    nodes: ["a", "b", "c", "d"].map(node),
    edges: [edge("a", "b"), edge("b", "a"), edge("a", "a"), edge("c", "missing"), edge("a", "b"), edge("d", "c"), edge("c", "d"), edge("b", "c")],
    revision: 1,
  };
  assert.deepEqual(shape(layoutTopology(small)), shape(referenceTopology(small)));
  assert.deepEqual(shape(layoutTopology(small)).edges, [["0", "1"], ["3", "2"], ["1", "2"]]);

  const results = representativeResults(5_000);
  const rows = results.results.bindings;
  const triples = bindingsToTriples(rows).filter((triple) => !triple.target.startsWith("__rdf_literal__"));
  const ids = [...new Set(triples.flatMap((triple) => [triple.source, triple.target]))];
  const graph = { nodes: ids.map(node), edges: triples.map((triple) => edge(triple.source, triple.target)), revision: 1 };
  const optimized = layoutTopology(graph);
  const reference = referenceTopology(graph);
  assert.deepEqual(shape(optimized), shape(reference));
  assert.deepEqual(layoutCommunities(graph).partition, louvain(reference, { randomWalk: false, resolution: 1 }));
});

// Rows to triples as it was: every alias of every role looked up in every row.
function referenceFind(binding, aliases) {
  for (const alias of aliases) {
    const exact = binding[alias];
    if (isSparqlTerm(exact)) return exact;
    const key = Object.keys(binding).find((candidate) => candidate.toLowerCase() === alias);
    if (key && isSparqlTerm(binding[key])) return binding[key];
  }
  return undefined;
}
const ALIASES = {
  source: ["source", "s", "subject", "from"],
  predicate: ["predicate", "p", "property", "relation", "edge"],
  target: ["target", "o", "object", "to"],
};
function referenceLabel(binding, role) {
  for (const alias of ALIASES[role]) {
    const candidate = referenceFind(binding, [`${alias}Label`, `${alias}_label`, `${alias}Name`]);
    if (candidate) return candidate.value;
  }
  return undefined;
}
function referenceTriples(bindings) {
  return bindings.flatMap((binding) => {
    const source = referenceFind(binding, ALIASES.source);
    const predicate = referenceFind(binding, ALIASES.predicate);
    const target = referenceFind(binding, ALIASES.target);
    if (!source || !predicate || !target || (source.type === "uri" && !isSafeSparqlIri(source.value))
      || (target.type === "uri" && !isSafeSparqlIri(target.value)) || predicate.type !== "uri" || !isSafeSparqlIri(predicate.value)) return [];
    const kind = (term) => (term.type === "uri" ? "iri" : term.type === "bnode" ? "blank" : "literal");
    return [{
      source: sparqlNodeId(source), sourceValue: source.value,
      sourceLabel: referenceLabel(binding, "source") || compactTerm(source.value), sourceLabelInput: referenceLabel(binding, "source") || null,
      sourceKind: kind(source), sourceDatatype: source.datatype, sourceLanguage: source["xml:lang"], sourceDirection: source["its:dir"],
      predicate: predicate.value, predicateLabel: predicateLabel(predicate.value, referenceLabel(binding, "predicate")),
      predicateLabelInput: referenceLabel(binding, "predicate") || null,
      target: sparqlNodeId(target), targetValue: target.value,
      targetLabel: referenceLabel(binding, "target") || compactTerm(target.value), targetLabelInput: referenceLabel(binding, "target") || null,
      targetKind: kind(target), targetDatatype: target.datatype, targetLanguage: target["xml:lang"], targetDirection: target["its:dir"],
    }];
  });
}

test("rows become the same triples as before, whatever their columns are called", () => {
  const uri = (value) => ({ type: "uri", value });
  const literal = (value, extra = {}) => ({ type: "literal", value, ...extra });
  const answers = [
    representativeResults(300).results.bindings,
    [
      { s: uri("urn:a"), p: uri("urn:p"), o: literal("x", { "xml:lang": "en" }), sLabel: literal("A"), pName: literal("pee") },
      { Subject: uri("urn:b"), PREDICATE: uri("urn:p"), Object: uri("urn:c"), subject_label: literal("") },
      { source: uri("urn:d"), predicate: uri("http://example.org/worksFor"), target: { type: "bnode", value: "b1" } },
      { source: { foo: 1 }, s: uri("urn:e"), predicate: uri("urn:p"), target: uri("urn:f"), sourceLabel: uri("urn:not-a-label") },
      { from: uri("urn:g"), relation: uri("urn:p"), to: uri("urn:h"), fromLabel: literal("Gee"), toName: literal("Aitch"), relationLabel: literal("http://x") },
      { source: uri("urn:i"), predicate: uri("urn:p") },
      { source: uri("not safe"), predicate: uri("urn:p"), target: uri("urn:j") },
      {},
    ],
    [{ source: uri("urn:a"), predicate: uri("urn:p"), target: uri("urn:b") }],
    [],
  ];
  for (const rows of answers) assert.deepEqual(bindingsToTriples(rows), referenceTriples(rows));
});

test("a layout takes the worker started ahead of it, and the next one is started afterwards", async () => {
  const created = [];
  class FakeWorker {
    constructor(url, options) {
      this.url = String(url);
      this.options = options;
      this.terminated = false;
      this.posted = [];
      created.push(this);
    }
    postMessage(message) {
      this.posted.push(message);
      queueMicrotask(() => this.onmessage?.({ data: { result: { positions: new Map(), bends: new Map() } } }));
    }
    terminate() {
      this.terminated = true;
    }
  }
  const saved = globalThis.Worker;
  globalThis.Worker = FakeWorker;
  try {
    releaseGraphLayoutWorker();
    warmGraphLayoutWorker();
    warmGraphLayoutWorker();
    assert.equal(created.length, 1, "one spare at a time");
    assert.match(created[0].url, /graph-layout-worker/);
    assert.deepEqual(created[0].options, { type: "module" });

    const graph = { nodes: [], edges: [], revision: 1 };
    await startGraphLayout(graph).promise;
    assert.equal(created[0].posted.length, 1, "the job went to the spare");
    assert.equal(created[0].terminated, true, "and the worker ended with it");
    await new Promise((resolve) => setTimeout(resolve, 0));
    assert.equal(created.length, 2, "a new spare is started after the job");

    const own = [];
    await startGraphLayout(graph, {}, () => {
      const worker = new FakeWorker("custom", {});
      own.push(worker);
      return worker;
    }).promise;
    assert.equal(own.length, 1, "a caller's own worker factory is used as given");
    assert.equal(created[1].posted.length, 0, "and leaves the spare for the page");

    const cancelled = startGraphLayout(graph);
    cancelled.cancel();
    await assert.rejects(cancelled.promise, { name: "AbortError" });
    assert.equal(created[1].terminated, true, "a cancelled job ends its worker");

    releaseGraphLayoutWorker();
    await new Promise((resolve) => setTimeout(resolve, 0));
    const spare = created.at(-1);
    releaseGraphLayoutWorker();
    assert.equal(spare.terminated, true, "leaving the page stops the spare");
  } finally {
    releaseGraphLayoutWorker();
    globalThis.Worker = saved;
  }
});
